@@ -83,7 +83,7 @@ function buildAbort (acRef) {
 }

 let patchMethodWarning = false
-let setRequestSignal, getRequestDispatcher, setRequestDispatcher, setRequestHeaders, getRequestState, setRequestState, removeRequestAbortListener
+let setRequestSignal, getRequestDispatcher, setRequestDispatcher, getRequestRetry, setRequestRetry, setRequestHeaders, getRequestState, setRequestState, removeRequestAbortListener

 // https://fetch.spec.whatwg.org/#request-class
 class Request {
@@ -93,6 +93,16 @@ class Request {
   /** @type {import('../../dispatcher/dispatcher')} */
   #dispatcher

+  /**
+   * Opt-in retry options forwarded to RetryHandler on dispatch (undici specific).
+   * `undefined` keeps the historical no-retry fetch behavior; `true` applies
+   * RetryHandler's defaults (ECONNRESET + UND_ERR_SOCKET + 5xx), and an object
+   * is passed through verbatim.
+   * @type {boolean | import('../../..').RetryHandler.RetryOptions | undefined}
+   * @see {@link https://github.com/nodejs/undici/issues/3492}
+   */
+  #retry
+
   /** @type {Headers} */
   #headers

@@ -134,6 +144,7 @@ class Request {
     // 5. If input is a string, then:
     if (typeof input === 'string') {
       this.#dispatcher = init.dispatcher
+      this.#retry = init.retry

       // 1. Let parsedURL be the result of parsing input with baseURL.
       // 2. If parsedURL is failure, then throw a TypeError.
@@ -170,6 +181,10 @@ class Request {
       signal = input.#signal

       this.#dispatcher = init.dispatcher || input.#dispatcher
+      // Prefer the init override, fall back to the Request we're cloning from.
+      // Explicit `init.retry === false` is honoured — users can disable retry
+      // when cloning a retry-enabled Request.
+      this.#retry = init.retry !== undefined ? init.retry : input.#retry
     }

     // 7. Let origin be this’s relevant settings object’s origin.
@@ -810,7 +825,7 @@ class Request {
     }

     // 4. Return clonedRequestObject.
-    return fromInnerRequest(clonedRequest, this.#dispatcher, ac.signal, getHeadersGuard(this.#headers))
+    return fromInnerRequest(clonedRequest, this.#dispatcher, ac.signal, getHeadersGuard(this.#headers), this.#retry)
   }

   [nodeUtil.inspect.custom] (depth, options) {
@@ -861,6 +876,22 @@ class Request {
      * @param {Request} request
      * @param {import('../../dispatcher/dispatcher')} newDispatcher
      */
+    /**
+     * @param {Request} request
+     * @returns {boolean | import('../../..').RetryHandler.RetryOptions | undefined}
+     */
+    getRequestRetry = (request) => {
+      return request.#retry
+    }
+
+    /**
+     * @param {Request} request
+     * @param {boolean | import('../../..').RetryHandler.RetryOptions | undefined} newRetry
+     */
+    setRequestRetry = (request, newRetry) => {
+      request.#retry = newRetry
+    }
+
     setRequestDispatcher = (request, newDispatcher) => {
       request.#dispatcher = newDispatcher
     }
@@ -979,11 +1010,14 @@ function cloneRequest (request) {
  * @param {'request' | 'immutable' | 'request-no-cors' | 'response' | 'none'} guard
  * @returns {Request}
  */
-function fromInnerRequest (innerRequest, dispatcher, signal, guard) {
+function fromInnerRequest (innerRequest, dispatcher, signal, guard, retry) {
   const request = new Request(kConstruct)
   setRequestState(request, innerRequest)
   setRequestDispatcher(request, dispatcher)
   setRequestSignal(request, signal)
+  if (retry !== undefined) {
+    setRequestRetry(request, retry)
+  }
   const headers = new Headers(kConstruct)
   setRequestHeaders(request, headers)
   setHeadersList(headers, innerRequest.headersList)
@@ -1121,6 +1155,14 @@ webidl.converters.RequestInit = webidl.dictionaryConverter([
     key: 'dispatcher', // undici specific option
     converter: webidl.converters.any
   },
+  {
+    key: 'retry', // undici specific option — see fixes #3492
+    // Accepts: boolean (true = enable with RetryHandler defaults, false = disabled),
+    // or a RetryOptions object forwarded verbatim to RetryAgent/RetryHandler.
+    // `any` here because RetryOptions is not a WebIDL dictionary and keeping it
+    // open lets us pass future RetryHandler fields through without churning here.
+    converter: webidl.converters.any
+  },
   {
     key: 'priority',
     converter: webidl.converters.DOMString,
@@ -1134,6 +1176,7 @@ module.exports = {
   fromInnerRequest,
   cloneRequest,
   getRequestDispatcher,
+  getRequestRetry,
   getRequestState,
   removeRequestAbortListener
 }

@@ -199,3 +199,13 @@ expectAssignable<Request>(new (class extends Request {
     return this
   }
 })('https://example.com'))
+
+// init.retry — see https://github.com/nodejs/undici/issues/3492
+const retryInitTrue: RequestInit = { retry: true }
+const retryInitFalse: RequestInit = { retry: false }
+const retryInitOptions: RequestInit = {
+  retry: { maxRetries: 3, minTimeout: 100, maxTimeout: 1_000, timeoutFactor: 2 }
+}
+expectAssignable<RequestInit>(retryInitTrue)
+expectAssignable<RequestInit>(retryInitFalse)
+expectAssignable<RequestInit>(retryInitOptions)
